fn target_linker<'a>(arguments: &[OsString], selections: &'a BTreeMap<String, PathBuf>) -> Option<&'a PathBuf> {
    let mut arguments = arguments.iter();
    while let Some(argument) = arguments.next() {
        let target = if argument == "--target" {
            arguments.next().and_then(|value| value.to_str())
        } else {
            argument.to_str().and_then(|value| value.strip_prefix("--target="))
        };
        if let Some(target) = target {
            return selections.get(target);
        }
    }
    None
}

